function appendMatureAfricanOrder(id,key,items){
  const article=window.deepArticles[id];
  if(!article)return;
  article[key]=article[key]||[];
  for(const item of items){
    if(!article[key].some(existing=>(item.id&&existing.id===item.id)||(item.href&&existing.href===item.href)))article[key].push(item);
  }
}

appendMatureAfricanOrder("south-africa","sections",[{id:"mature-order",title:"Mature order, 1986–2000",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-s8h3s writer=g kind=revision created=2026-08-16T13:00:00-06:00 --><p>Continuation of apartheid into the 2000s with administrative change, and increased Pretoria leverage from space tracking, strategic materials, the Cape route, and regional cooperation, are accepted mature-order development.<sup class='canon-note' data-provenance='e'>[e]</sup> The author establishes prolonged racial rule but leaves its endpoint and reforms open.<sup class='canon-note' data-provenance='a'>[a]</sup> See <a href='apartheid-in-the-space-age.html'>Apartheid in the Space Age</a>.</p><!-- altwwii-writer-block:end -->"}]);
appendMatureAfricanOrder("south-africa","related",[{href:"apartheid-in-the-space-age.html",kicker:"Late-century system",label:"Apartheid in the Space Age"},{href:"southern-african-population-policy.html",kicker:"Family policy",label:"Southern African Population Policy"},{href:"african-order-in-2000.html",kicker:"Continental baseline",label:"African Order in 2000"}]);
appendMatureAfricanOrder("rhodesia","sections",[{id:"mature-order",title:"Mature settler order",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-r9j4s writer=g kind=revision created=2026-08-16T13:30:00-06:00 --><p>The author establishes broad late-century domestic latitude for Rhodesia so long as it remains in the Commonwealth, uses sterling, and follows major British strategic decisions, together with increasingly practical relations with South Africa.<sup class='canon-note' data-provenance='a'>[a]</sup> Salisbury's precise authority by 2000 and its constitutional relationship to the Crown, Commonwealth, and Central African framework remain open. See <a href='rhodesian-settler-order-2000.html'>Rhodesian Settler Order in 2000</a>.</p><!-- altwwii-writer-block:end -->"}]);
appendMatureAfricanOrder("rhodesia","related",[{href:"rhodesian-settler-order-2000.html",kicker:"Late-century system",label:"Rhodesian Settler Order in 2000"},{href:"southern-african-population-policy.html",kicker:"Family policy",label:"Southern African Population Policy"},{href:"african-order-in-2000.html",kicker:"Continental baseline",label:"African Order in 2000"}]);
appendMatureAfricanOrder("british-africa","sections",[{id:"africa-2000",title:"African order in 2000",html:"<!-- altwwii-writer-block:start id=wb-g-20260816-ca1b7 writer=g kind=revision created=2026-08-16T07:10:00-06:00 --><p>The author directly establishes broad conditional discretion for Pretoria and Salisbury, prolonged racial rule, and improving practical regional relations.<sup class='canon-note' data-provenance='a'>[a]</sup> Stronger Crown leverage in East Africa and the complete 2000 comparison of regional détente with continuing racial and colonial systems are accepted synthesis.<sup class='canon-note' data-provenance='e'>[e]</sup> Constitutional settlements and later outcomes remain open. See <a href='african-order-in-2000.html'>African Order in 2000</a>.</p><!-- altwwii-writer-block:end -->"}]);
appendMatureAfricanOrder("british-africa","related",[{href:"african-order-in-2000.html",kicker:"Millennium overview",label:"African Order in 2000"},{href:"african-opposition-in-late-commonwealth.html",kicker:"Political opposition",label:"African Opposition in the Late Commonwealth"}]);
for(const id of ["kenya","uganda","tanganyika"]){
  appendMatureAfricanOrder(id,"sections",[{id:"late-autonomy",title:"Late-century autonomy",html:id==="kenya"?"<!-- altwwii-writer-block:start id=wb-g-20260816-kq4y8 writer=g kind=revision created=2026-08-16T07:15:00-06:00 --><p>The author directly establishes broad conditional Kenyan domestic discretion within the Commonwealth.<sup class='canon-note' data-provenance='a'>[a]</sup> Substantial internal government by 2000 within a separate settlement and shared East African services, with greater London leverage than in South Africa or Rhodesia, is accepted development.<sup class='canon-note' data-provenance='e'>[e]</sup> The constitutional endpoint remains open. See <a href='east-african-autonomy-settlement.html'>East African Autonomy Settlement</a>.</p><!-- altwwii-writer-block:end -->":id==="uganda"?"<!-- altwwii-writer-block:start id=wb-g-20260816-us3z7 writer=g kind=revision created=2026-08-16T07:25:00-06:00 --><p>Substantial Ugandan domestic government by 2000 within a separate protected-federal settlement and shared East African services, with greater London leverage than in South Africa or Rhodesia, is accepted development.<sup class='canon-note' data-provenance='e'>[e]</sup> Its powers, external relationship, and sovereignty endpoint remain open. See <a href='east-african-autonomy-settlement.html'>East African Autonomy Settlement</a>.</p><!-- altwwii-writer-block:end -->":"<!-- altwwii-writer-block:start id=wb-g-20260816-tl4l8 writer=g kind=revision created=2026-08-16T07:25:00-06:00 --><p>Substantial Tanganyikan domestic government by 2000 within a separate Crown-state settlement and shared East African services, with greater London leverage than in South Africa or Rhodesia, is accepted development.<sup class='canon-note' data-provenance='e'>[e]</sup> Its powers, external relationship, and sovereignty endpoint remain open. See <a href='east-african-autonomy-settlement.html'>East African Autonomy Settlement</a>.</p><!-- altwwii-writer-block:end -->"}]);
  appendMatureAfricanOrder(id,"related",[{href:"east-african-autonomy-settlement.html",kicker:"Late-century settlement",label:"East African Autonomy Settlement"},{href:"african-order-in-2000.html",kicker:"Continental baseline",label:"African Order in 2000"}]);
}
for(const id of ["portuguese-angola","portuguese-mozambique"]){
  appendMatureAfricanOrder(id,"sections",[{id:"after-consolidation",title:"After consolidation, 1980–2000",html:"<p>Large organized revolt gives way to denser police, court, registry, road, school, customs, and market administration. Portuguese sovereignty and provincial status continue. See <a href='portuguese-africa-after-consolidation.html'>Portuguese Africa after Consolidation</a>.</p>"}]);
  appendMatureAfricanOrder(id,"related",[{href:"portuguese-africa-after-consolidation.html",kicker:"Late-century system",label:"Portuguese Africa after Consolidation"},{href:"african-order-in-2000.html",kicker:"Continental baseline",label:"African Order in 2000"}]);
}
appendMatureAfricanOrder("world-in-2000","sections",[{id:"africa",title:"African political order",html:"<p>Southern and eastern Africa contains Commonwealth settler and Crown-linked governments, Portuguese overseas provinces, and German Mittelafrika. Practical regional liaison expands while apartheid, minority rule, colonial sovereignty, and racially differentiated population policy remain in place. See <a href='african-order-in-2000.html'>African Order in 2000</a>.</p>"}]);
